  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: waive
waive:
  class: net.officefloor.hq.app.claim.WaiveClaim
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaims
  govern: [ transaction ]
# Add a comment to a claim (not an empty one). Responds with the sheet's claims.
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: comment
comment:
  class: net.officefloor.hq.app.claim.CommentClaim
